sealed class TextTarget {
    
    object Server : TextTarget()
    
    
    object Channel : TextTarget()
    
    
    data class Client(
        val `id`: kotlin.UShort) : TextTarget()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeTextTarget : FfiConverterRustBuffer<TextTarget>{
    override fun read(buf: ByteBuffer): TextTarget {
        return when(buf.getInt()) {
            1 -> TextTarget.Server
            2 -> TextTarget.Channel
            3 -> TextTarget.Client(
                FfiConverterUShort.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: TextTarget): ULong = when(value) {
        is TextTarget.Server -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is TextTarget.Channel -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is TextTarget.Client -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUShort.allocationSize(value.`id`)
            )
        }
    }

    override fun write(value: TextTarget, buf: ByteBuffer) {
        when(value) {
            is TextTarget.Server -> {
                buf.putInt(1)
                Unit
            }
            is TextTarget.Channel -> {
                buf.putInt(2)
                Unit
            }
            is TextTarget.Client -> {
                buf.putInt(3)
                FfiConverterUShort.write(value.`id`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







sealed class TsException: kotlin.Exception() {
    
    class Failed(
        
        val v1: kotlin.String
        ) : TsException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<TsException> {
        override fun lift(error_buf: RustBuffer.ByValue): TsException = FfiConverterTypeTsError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeTsError : FfiConverterRustBuffer<TsException> {
    override fun read(buf: ByteBuffer): TsException {
        

        return when(buf.getInt()) {
            1 -> TsException.Failed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: TsException): ULong {
        return when(value) {
            is TsException.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: TsException, buf: ByteBuffer) {
        when(value) {
            is TsException.Failed -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




